            { stem: "ともだちがあたらしいくるまをかいました。なんといいますか。", options: ["おめでとうございます。", "すみません。", "ざんねんですね。", "だいじょうぶですか。"], answer: 1, explanation: "おめでとうございます to congratulate." },
            { stem: "レストランでちゅうもんします。なんといいますか。", options: ["いただきます。", "すみません、ちゅうもんをおねがいします。", "ごちそうさまでした。", "おかわりください。"], answer: 2, explanation: "すみません、ちゅうもんをおねがいします to order." },
            { stem: "あなたはでんしゃのなかで、おばあさんがたっています。せきをゆずりたいです。", options: ["どうぞ、おすわりください。", "すわってください。", "ここにすわりなさい。", "すわらないでください。"], answer: 1, explanation: "どうぞ、おすわりください is the polite way to offer a seat." },
            { stem: "ともだちのたんじょうびです。プレゼントをわたすとき、なんといいますか。", options: ["これ、どうぞ。", "これ、ください。", "これ、もらいます。", "これ、すみません。"], answer: 1, explanation: "これ、どうぞ when giving a present." }
