          transcript: "<p>おとこ：おかあさん、あしたのおべんとう、なにがいい？<br>おんな：そうねえ、おにぎりとからあげをおねがい。<br>おとこ：たまごやきは？<br>おんな：うん、それもいれてくれるとうれしいわ。あ、それからくだものもね。<br>おとこ：わかった。りんごでいい？<br>おんな：ありがとう。</p>",
