            { stem: "（ 4 ）にはいることばはどれですか。", options: ["プレゼント", "おかね", "でんわ", "てがみ"], answer: 1, explanation: "プレゼントをあげました (gave a present)." },
            { stem: "（ 5 ）にはいることばはどれですか。", options: ["あさ", "ひる", "よる９じ", "よる１２じ"], answer: 3, explanation: "よる９じごろおわりました (ended around 9 PM)." }
